  1	import React, { useState, useEffect, useRef, useCallback } from 'react';
  2	import { createPortal } from 'react-dom';
  3	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
  4	import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
  5	import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
  6	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
  7	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
  8	import { ZimmTextInput } from 'app/components/ui-kits/atoms/zimmTextInput';
  9	import { ZimmInputAction } from 'app/components/ui-kits/molecules/zimmInputAction';
 10	import { isSafeHref } from 'app/utils/safeHref';
 11	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
 12	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
 13	import { useHistory } from 'react-router-dom';
 14	import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
 15	import type { FooterConfigEntry } from 'app/types/contentful';
 16	import { FOOTER_FIXTURE } from './contentfulFixture';
 17	
 18	// Named constant to avoid magic string comparison in the render tree
 19	/** Non-breaking space. Marks a label whose line break is intentional — see the nav item below. */
 20	const NBSP = '\u00A0';
 21	// Locale control label. Hardcoded, and deliberately NOT fixture data — region and currency
 22	// come from site config (config/default.js: defaultSite 'ZimmermannAU'), not Contentful, so
 23	// FooterConfigEntry has no field for them. Set to match the site the app actually serves at
 24	// '/'; it previously read "United States (USD) / ENG" on an AU storefront. The real fix reads
 25	// site.l10n.defaultLocale and the site's currency via useMultiSite when the locale selector
 26	// lands, at which point this constant goes away rather than getting a different literal.
 27	const LOCALE_LABEL_PLACEHOLDER = 'Australia (AUD) / ENG';
 28	
 29	// ---------------------------------------------------------------------------
 30	// Types
 31	// ---------------------------------------------------------------------------
 32	type FooterProps = {
 33	  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from contentfulFixture.ts in stories/tests. */
 34	  data: FooterConfigEntry;
 35	  copyrightYear?: number;
 36	  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
 37	  initialSubscribed?: boolean;
 38	  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
 39	   *  noop so the presentational Footer never navigates on its own. */
 40	  onLogoClick?: () => void;
 41	  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
 42	  privacyPolicyHref?: string;
 43	};
 44	
 45	// ---------------------------------------------------------------------------
 46	// All footer styling lives in theme/components/footer.ts and is consumed via
 47	// useMultiStyleConfig('ZimmFooter') → __css. Nothing is styled at the call site.
 48	// ---------------------------------------------------------------------------
 49	
 50	// Subscribe heading ("Keep in Touch") — same type scale as navigation, distinct colour and lineHeight
 51	// colour.ts note: text.inverseGrey and text.muted are both #969696 as of develop commit 6fa8e92
 52	// lineHeight override: textStyles.navigation token says 'normal' (≈14.4px at 12px font), but
 53	// ---------------------------------------------------------------------------
 54	// Subscribe modal (HPC-035 + HPC-037)
 55	// Rendered via createPortal so the overlay escapes the footer stacking context.
 56	// ---------------------------------------------------------------------------
 57	// HPC-037 copy — update when UX supplies final content
 58	const PRIVACY_CONSENT_COPY = 'By providing your details, you agree to receive email updates from Zimmermann. View our';
 59	const ACCESSIBILITY_DISCLAIMER_COPY =
 60	  'Zimmermann is committed to providing accessible services. ' +
 61	  'If you experience any difficulty, please contact us for assistance.';
 62	
 63	type SubscribeModalProps = {
 64	  isOpen: boolean;
 65	  onClose: () => void;
 66	  onSubmit: (firstName: string, lastName: string) => void;
 67	  privacyPolicyHref: string;
 68	};
 69	
 70	const SubscribeModal = ({ isOpen, onClose, onSubmit, privacyPolicyHref }: SubscribeModalProps) => {
 71	  const [mounted, setMounted] = useState(false);
 72	  const formRef = useRef<HTMLFormElement>(null);
 73	  const firstFocusRef = useRef<HTMLDivElement>(null);
 74	  const triggerRef = useRef<Element | null>(null);
 75	  const styles = useMultiStyleConfig('ZimmFooter', {});
 76	
 77	  useEffect(() => {
 78	    setMounted(true);
 79	  }, []);
 80	
 81	  // Save the trigger element on open so focus can be restored on close
 82	  useEffect(() => {
 83	    if (isOpen) {
 84	      triggerRef.current = document.activeElement;
 85	      // Defer so the portal has rendered before we try to focus inside it
 86	      const id = setTimeout(() => {
 87	        const firstInput = firstFocusRef.current?.querySelector<HTMLElement>('input');
 88	        firstInput?.focus();
 89	      }, 0);
 90	      return () => clearTimeout(id);
 91	    } else {
 92	      // Return focus to the element that opened the modal
 93	      if (triggerRef.current instanceof HTMLElement) {
 94	        triggerRef.current.focus();
 95	      }
 96	    }
 97	  }, [isOpen]);
 98	
 99	  // Lock body scroll while modal is open
100	  useEffect(() => {
101	    if (!isOpen) return;
102	    const prev = document.body.style.overflow;
103	    document.body.style.overflow = 'hidden';
104	    return () => {
105	      document.body.style.overflow = prev;
106	    };
107	  }, [isOpen]);
108	
109	  // Keyboard: Escape to close, Tab trap within modal
110	  const handleKeyDown = useCallback(
111	    (e: KeyboardEvent) => {
112	      if (e.key === 'Escape') {
113	        onClose();
114	        return;
115	      }
116	      if (e.key !== 'Tab' || !formRef.current) return;
117	
118	      const focusable = Array.from(
119	        formRef.current.querySelectorAll<HTMLElement>(
120	          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
121	        ),
122	      ).filter((el) => !el.hasAttribute('disabled'));
123	
124	      const first = focusable[0];
125	      const last = focusable[focusable.length - 1];
126	
127	      if (e.shiftKey && document.activeElement === first) {
128	        e.preventDefault();
129	        last?.focus();
130	      } else if (!e.shiftKey && document.activeElement === last) {
131	        e.preventDefault();
132	        first?.focus();
133	      }
134	    },
135	    [onClose],
136	  );
137	
138	  useEffect(() => {
139	    if (!isOpen) return;
140	    document.addEventListener('keydown', handleKeyDown);
141	    return () => document.removeEventListener('keydown', handleKeyDown);
142	  }, [isOpen, handleKeyDown]);
143	
144	  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
145	    e.preventDefault();
146	    const form = e.currentTarget;
147	    const firstName = (form.elements.namedItem('firstName') as HTMLInputElement)?.value ?? '';
148	    const lastName = (form.elements.namedItem('lastName') as HTMLInputElement)?.value ?? '';
149	    onSubmit(firstName.trim(), lastName.trim());
150	  };
151	
152	  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
153	    if (e.target === e.currentTarget) onClose();
154	  };
155	
156	  if (!mounted || !isOpen) return null;
157	
158	  return createPortal(
159	    <chakra.div role="presentation" onClick={handleBackdropClick} __css={styles.modalOverlay}>
160	      <chakra.div
161	        role="dialog"
162	        aria-modal="true"
163	        aria-labelledby="zimm-subscribe-modal-title"
164	        aria-describedby="zimm-subscribe-modal-consent"
165	        __css={styles.subscribeModalPanel}
166	      >
167	        <form ref={formRef} onSubmit={handleFormSubmit} noValidate>
168	          {/* Title */}
169	          <chakra.h2 id="zimm-subscribe-modal-title" __css={styles.modalTitle}>
170	            Join Us
171	          </chakra.h2>
172	
173	          {/* First Name */}
174	          <chakra.div ref={firstFocusRef} __css={styles.modalField}>
175	            <ZimmTextInput label="First Name" name="firstName" />
176	          </chakra.div>
177	
178	          {/* Last Name */}
179	          <chakra.div __css={styles.modalFieldLast}>
180	            <ZimmTextInput label="Last Name" name="lastName" />
181	          </chakra.div>
182	
183	          {/* Privacy consent copy (HPC-037) */}
184	          <chakra.p id="zimm-subscribe-modal-consent" __css={styles.modalConsent}>
185	            {PRIVACY_CONSENT_COPY}{' '}
186	            {/* Same guard as the contact channels: privacyPolicyHref is a prop, so a caller
187	                can supply anything. Unsafe or absent renders the label as plain text rather
188	                than an anchor that goes nowhere. */}
189	            {isSafeHref(privacyPolicyHref) ? (
190	              <chakra.a href={privacyPolicyHref} __css={styles.modalConsentLink}>
191	                Privacy Policy
192	              </chakra.a>
193	            ) : (
194	              <chakra.span __css={styles.modalConsentLink}>Privacy Policy</chakra.span>
195	            )}
196	            .
197	          </chakra.p>
198	
199	          {/* Accessibility disclaimer (HPC-037) */}
200	          <chakra.p __css={styles.modalDisclaimer}>{ACCESSIBILITY_DISCLAIMER_COPY}</chakra.p>
201	
202	          {/* Actions */}
203	          <chakra.div __css={styles.modalActions}>
204	            <ZimmButton variant="secondary" size="medium" label="Cancel" type="button" onClick={onClose} />
205	            <ZimmButton variant="primary" size="medium" label="Continue" type="submit" />
206	          </chakra.div>
207	        </form>
208	      </chakra.div>
209	    </chakra.div>,
210	    document.body,
211	  );
212	};
