422	// ---------------------------------------------------------------------------
423	// Footer
424	// ---------------------------------------------------------------------------
425	
426	/**
427	 * Zimmermann global footer — presentational. Receives its content as props and
428	 * fetches nothing, matching every other Contentful-backed component in the repo
429	 * (`DuplexSection`, `HeroBanner`, `ProductHero`, `VideoEmbed`).
430	 *
431	 * `data` is required by design: static content belongs in the story or in the
432	 * container below, never baked into the component that renders production UI.
433	 * Omneo email submit and Cookie Settings are separate stories (HPC-035, HPC-038).
434	 */
435	export const Footer = ({
436	  data,
437	  copyrightYear = new Date().getFullYear(),
438	  initialSubscribed = false,
439	  privacyPolicyHref = '#',
440	  onLogoClick = noop,
441	}: FooterProps) => {
442	  const {
443	    subscribeHeading,
444	    subscribeBody,
445	    navGroups,
446	    legalLinks = [],
447	    copyrightOwner,
448	    phoneHref,
449	    whatsAppHref,
450	    emailHref,
451	  } = data.fields;
452	
453	  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
454	  const styles = useMultiStyleConfig('ZimmFooter', {});
455	
456	  return (
457	    <chakra.footer role="contentinfo" __css={styles.container}>
458	      <chakra.div __css={styles.main}>
459	        <chakra.div __css={styles.contentRow}>
460	          <chakra.div __css={styles.subscribe}>
461	            <SubscribeSection
462	              heading={subscribeHeading ?? ''}
463	              body={subscribeBody ?? ''}
464	              initialSubscribed={initialSubscribed}
465	              privacyPolicyHref={privacyPolicyHref}
466	            />
467	          </chakra.div>
468	
469	          <chakra.div __css={styles.links}>
470	            <chakra.div __css={styles.linksInner}>
471	              {navGroups.map((group) => (
472	                <chakra.div key={group.sys.id} __css={styles.linkCol}>
473	                  {/* Figma section column: flex-col gap-16px — the column gap replaces
474	                                        marginBottom on the heading. Contact heading has 4px left offset. */}
475	                  <chakra.p
476	                    __css={{
477	                      ...styles.columnHeading,
478	                      ...(group.fields.showContactChannels ? { paddingLeft: '2xs' } : {}),
479	                    }}
480	                  >
481	                    {group.fields.heading}
482	                  </chakra.p>
483	                  {/* Figma Links div (2228:19423): flex-col, items-start, width 100%, gap 0.
484	                      DELIBERATE DEVIATION: Figma puts the Contact items at x=0 while indenting
485	                      only its heading 4px (wrapper 40000407:22289) — About and Help headings sit
486	                      flush at 0, so that asymmetry reads as a stray wrapper rather than intent.
487	                      We indent the Contact items to match their heading so the column aligns as a
488	                      unit. The icon row below needs no indent: its 24px box centres a 16px glyph,
489	                      so the glyph edge already lands at 4px. Pending Kiera. */}
490	                  <chakra.ul __css={styles.linkList}>
491	                    {group.fields.links.map((link) => (
492	                      <chakra.li
493	                        key={link.sys.id}
494	                        __css={{
495	                          ...styles.linkListItem,
496	                          ...(group.fields.showContactChannels ? { paddingLeft: '2xs' } : {}),
497	                        }}
498	                      >
499	                        {/* Each item h-[24px] items-center, no gap. ZimmNavItem's baseStyle supplies
500	                            minHeight 24px, whiteSpace normal (so the label below can wrap) and uppercase.
501	
502	                            width:min-content only for labels that carry a non-breaking space. A wrapped
503	                            element takes the AVAILABLE width, not its longest line, so without this the
504	                            Acknowledgement item filled linkCol's 160px cap while its longest line is
505	                            115px — 45px of dead space that pushed the Contact column right, against
506	                            Figma where every column hugs its content. min-content resolves to the widest
507	                            unbreakable run, which the NBSP makes exactly "ACKNOWLEDGEMENT" (115px).
508	                            It must stay gated: applied to a single-line label it collapses to the longest
509	                            word and wraps it ("Book an Appointment" 131px -> 76px, two lines). */}
510	                        <ZimmNavItem
511	                          href={link.fields.href}
512	                          label={link.fields.label}
513	                          inverse
514	                          sx={link.fields.label.includes(NBSP) ? { width: 'min-content' } : undefined}
515	                        />
516	                      </chakra.li>
517	                    ))}
518	                    {/* Contact channels are the LAST CHILD OF THE LIST, not a sibling of it —
519	                        Figma's Icon-list (40002081:14616) sits inside Links at y=72, directly
520	                        after "CONNECT WITH US" ends at y=72, so only its own 4px padding-top
521	                        separates them. Rendered outside the <ul> it instead picked up linkCol's
522	                        16px column gap and sat 20px low against Figma's 4px. */}
523	                    {group.fields.showContactChannels && (
524	                      <chakra.li __css={styles.linkListItem}>
525	                        <ContactIconRow phoneHref={phoneHref} whatsAppHref={whatsAppHref} emailHref={emailHref} />
526	                      </chakra.li>
527	                    )}
528	                  </chakra.ul>
529	                </chakra.div>
530	              ))}
531	            </chakra.div>
532	          </chakra.div>
533	        </chakra.div>
534	
535	        <chakra.div __css={styles.logo}>
536	          {/* Button + programmatic nav, matching the header's wordmark rather than an <a href>.
537	              The handler comes from FooterContainer — see the note there on why it uses
538	              buildUrl + history.push rather than useNavigation. styles.logoButton is a chrome
539	              reset only, so the logo keeps its own geometry. */}
540	          <chakra.button type="button" aria-label="Zimmermann home" onClick={onLogoClick} __css={styles.logoButton}>
541	            <ZimmLogo variant="inverse" />
542	          </chakra.button>
543	        </chakra.div>
544	      </chakra.div>
545	
546	      <BottomBar copyrightYear={copyrightYear} copyrightOwner={copyrightOwner ?? ''} legalLinks={legalItems} />
547	    </chakra.footer>
548	  );
549	};
