    42	
    43	// Figma iconography spec: node 1892:59595 — 34 of 34 types implemented.
    44	export type ZimmIconType =
    45	  | 'arrow-down'
    46	  | 'arrow-link'
    47	  | 'arrow-up'
    48	  | 'bag'
    49	  | 'bag-selected'
    50	  | 'calendar'
