    57	  | 'chevron-right'
    58	  | 'chevron-up'
    59	  | 'close'
    60	  | 'delete'
    61	  | 'edit'
    62	  | 'external-link'
    63	  | 'info'
    64	  | 'info-selected'
    65	  | 'location'
    66	  | 'menu'
    67	  | 'minus'
    68	  | 'mute'
    69	  | 'password'
    70	  | 'pause'
    71	  | 'play'
    72	  | 'plus'
    73	  | 'profile'
    74	  | 'search'
    75	  | 'share'
    76	  | 'share-2'
    77	  | 'wishlist'
    78	  | 'wishlist-selected'
    79	  // Footer-specific custom icons — not yet in Figma node 1892:59595,
    80	  // pending addition to the iconography spec in the next design sync.
    81	  | 'phone'
    82	  | 'whatsapp'
    83	  | 'email';
    84	
    85	export type ZimmIconSize = keyof typeof iconSizes;
    86	
    87	type ZimmIconProps = {
    88	  type: ZimmIconType;
    89	  size?: ZimmIconSize;
    90	  /** Pass Chakra token strings or CSS keywords (e.g. 'text.primary', 'currentColor').
    91	   *  Do not pass hardcoded hex values — use theme tokens. */
    92	  color?: string;
    93	} & ({ 'aria-hidden': true; 'aria-label'?: never } | { 'aria-hidden'?: never; 'aria-label': string });
    94	
    95	const ICON_MAP = {
    96	  'arrow-down': ArrowDownIcon,
    97	  'arrow-link': ArrowLinkIcon,
    98	  'arrow-up': ArrowUpIcon,
    99	  bag: BagIcon,
   100	  'bag-selected': BagSelectedIcon,
   101	  calendar: CalendarIcon,
   102	  carousel: CarouselIcon,
   103	  'carousel-selected': CarouselSelectedIcon,
   104	  chat: ChatIcon,
   105	  check: CheckIcon,
   106	  'chevron-down': ChevronDownIcon,
   107	  'chevron-left': ChevronLeftIcon,
   108	  'chevron-right': ChevronRightIcon,
   109	  'chevron-up': ChevronUpIcon,
   110	  close: CloseIcon,
   111	  delete: DeleteIcon,
   112	  edit: EditIcon,
   113	  'external-link': ExternalLinkIcon,
   114	  info: InfoIcon,
   115	  'info-selected': InfoSelectedIcon,
   116	  location: LocationIcon,
   117	  menu: MenuIcon,
   118	  minus: MinusIcon,
   119	  mute: MuteIcon,
   120	  password: PasswordShowIcon,
   121	  pause: PauseIcon,
   122	  play: PlayIcon,
   123	  plus: PlusIcon,
   124	  profile: ProfileIcon,
   125	  search: SearchIcon,
   126	  share: ShareIcon,
   127	  'share-2': ShareTwoIcon,
   128	  wishlist: FavouritesIcon,
   129	  'wishlist-selected': FavouritesSolidIcon,
   130	  // Footer-specific custom icons — not yet in Figma node 1892:59595,
   131	  // pending addition to the iconography spec in the next design sync.
   132	  phone: PhoneIcon,
   133	  whatsapp: WhatsAppIcon,
   134	  email: EmailIcon,
   135	} as const;
   136	
   137	/** Atom — single icon from the Zimmermann icon set. Mirrors zimm-icon contract. */
   138	export const ZimmIcon = ({ type, size = 'md', color = 'currentColor', ...aria }: ZimmIconProps) => {
   139	  const Icon = ICON_MAP[type];
   140	  // TypeScript cannot index a discriminated union type directly — each branch must be cast
   141	  // individually to access the relevant key without a type error.
   142	  const ariaHidden = (aria as { 'aria-hidden'?: boolean })['aria-hidden'];
   143	  const ariaLabel = (aria as { 'aria-label'?: string })['aria-label'];
   144	  return (
   145	    <Icon
   146	      boxSize={iconSizes[size]}
   147	      color={color}
   148	      aria-hidden={ariaHidden}
   149	      aria-label={ariaLabel}
   150	      role={ariaLabel ? 'img' : undefined}
   151	    />
   152	  );
   153	};

