console.log('declared but NOT in baseStyle:', parts.filter(p=>!defined.includes(p)));
console.log('in baseStyle but NOT declared in parts:', defined.filter(d=>!parts.includes(d)));
console.log('used in index.tsx:', used.length);
console.log('used but NOT in baseStyle:', used.filter(u=>!defined.includes(u)));
console.log('baseStyle keys never used in index.tsx:', defined.filter(d=>!used.includes(d)));
